from torch.utils.cpp_extension import load_inline

src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cstdint>

template <typename scalar_t>
__global__ void argmax_dim0_kernel(const scalar_t* __restrict__ input,
                                   int64_t* __restrict__ output,
                                   int64_t batch,
                                   int64_t dim1,
                                   int64_t dim2) {
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    int64_t total = dim1 * dim2;
    if (idx >= total) return;

    int64_t i = idx / dim2;          // index in dim1
    int64_t j = idx % dim2;          // index in dim2

    int64_t best = 0;
    scalar_t best_val = input[0 * dim1 * dim2 + i * dim2 + j];
    for (int64_t b = 1; b < batch; ++b) {
        scalar_t val = input[b * dim1 * dim2 + i * dim2 + j];
        if (__hgt(val, best_val)) {
            best_val = val;
            best = b;
        }
    }
    output[idx] = best;
}

template <typename scalar_t>
__global__ void argmax_dim1_kernel(const scalar_t* __restrict__ input,
                                   int64_t* __restrict__ output,
                                   int64_t batch,
                                   int64_t dim1,
                                   int64_t dim2) {
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    int64_t total = batch * dim2;
    if (idx >= total) return;

    int64_t b = idx / dim2;          // batch index
    int64_t j = idx % dim2;          // dim2 index

    int64_t best = 0;
    scalar_t best_val = input[b * dim1 * dim2 + 0 * dim2 + j];
    for (int64_t i = 1; i < dim1; ++i) {
        scalar_t val = input[b * dim1 * dim2 + i * dim2 + j];
        if (__hgt(val, best_val)) {
            best_val = val;
            best = i;
        }
    }
    output[idx] = best;
}

template <typename scalar_t>
__global__ void argmax_dim2_kernel(const scalar_t* __restrict__ input,
                                   int64_t* __restrict__ output,
                                   int64_t batch,
                                   int64_t dim1,
                                   int64_t dim2) {
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    int64_t total = batch * dim1;
    if (idx >= total) return;

    int64_t b = idx / dim1;          // batch index
    int64_t i = idx % dim1;          // dim1 index

    int64_t best = 0;
    scalar_t best_val = input[b * dim1 * dim2 + i * dim2 + 0];
    for (int64_t j = 1; j < dim2; ++j) {
        scalar_t val = input[b * dim1 * dim2 + i * dim2 + j];
        if (__hgt(val, best_val)) {
            best_val = val;
            best = j;
        }
    }
    output[idx] = best;
}

// Dispatcher
torch::Tensor argmax_cuda(torch::Tensor input, int64_t dim) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.scalar_type() == torch::kHalf, "input must be fp16");
    TORCH_CHECK(dim >= 0 && dim < input.dim(), "dim out of range");

    const int64_t batch = input.size(0);
    const int64_t dim1  = input.size(1);
    const int64_t dim2  = input.size(2);

    torch::Tensor output;
    int64_t out_numel;
    if (dim == 0) {
        out_numel = dim1 * dim2;
        output = torch::empty({dim1, dim2}, torch::dtype(torch::kLong).device(input.device()));
        const int threads = 256;
        const int blocks = (out_numel + threads - 1) / threads;
        argmax_dim0_kernel<__half><<<blocks, threads>>>(
            reinterpret_cast<const __half*>(input.data_ptr()),
            output.data_ptr<int64_t>(),
            batch, dim1, dim2);
    } else if (dim == 1) {
        out_numel = batch * dim2;
        output = torch::empty({batch, dim2}, torch::dtype(torch::kLong).device(input.device()));
        const int threads = 256;
        const int blocks = (out_numel + threads - 1) / threads;
        argmax_dim1_kernel<__half><<<blocks, threads>>>(
            reinterpret_cast<const __half*>(input.data_ptr()),
            output.data_ptr<int64_t>(),
            batch, dim1, dim2);
    } else { // dim == 2
        out_numel = batch * dim1;
        output = torch::empty({batch, dim1}, torch::dtype(torch::kLong).device(input.device()));
        const int threads = 256;
        const int blocks = (out_numel + threads - 1) / threads;
        argmax_dim2_kernel<__half><<<blocks, threads>>>(
            reinterpret_cast<const __half*>(input.data_ptr()),
            output.data_ptr<int64_t>(),
            batch, dim1, dim2);
    }

    // sync for debugging; can be removed for performance
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA kernel launch error: %s\\n", cudaGetErrorString(err));
    }
    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("argmax_cuda", &argmax_cuda, "Argmax over a dimension (CUDA, fp16 input)");
}
'''

# compile the inline extension
argmax_module = load_inline(name='argmax_ext',
                            cpp_sources='',
                            cuda_sources=src,
                            functions=['argmax_cuda'],
                            verbose=False)

class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return argmax_module.argmax_cuda(x, self.dim)

# Example usage (can be removed in actual test harness)
